    // lit edge where density falls off toward the light, darker cores
    let lit = clamp(0.6 + (n - n2) * 4.0, 0.25, 1.2);
    let hz = s.horizon.rgb;
    let base = mix(hz, vec3f(max(hz.r, max(hz.g, hz.b))), 0.55) * 1.2;
